using System.Collections.Generic;
using Astrea;
using Astrea.RunModifiers;
using UnityEngine;

[CreateAssetMenu(fileName = "ForgeSafeDiceRewardForgeModifier", menuName = "Data/Battle/Omens System/Omen Data/Any/ForgeSafeDiceRewardForgeModifier", order = 0)]
public class ForgeSafeDiceRewardForgeModifier : DiceRewardForgeModifier
{
	[SerializeField]
	private GenericShop genericShop;

	public override Dice GetModifiedDice(Dice dice)
	{
		if (dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.SafeDieTier)
		{
			return dice;
		}
		List<ShopItem> randomShopItems = genericShop.RandomShopItems.DuplicateAsList();
		randomShopItems.RemoveAll(delegate(ShopItem item)
		{
			ForgeDiceReward forgeDiceReward2 = item.Reward as ForgeDiceReward;
			return item.RawCost != 200 || (forgeDiceReward2.EnableCharacter && forgeDiceReward2.Character != ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter);
		});
		Dice dice2 = Object.Instantiate(dice);
		dice2.GetDiceFaces();
		int num = ((ReferenceSingleton<RunModifiersManager>.Instance.DicesmithFeverDiceRewardForgeModifier != null) ? 4 : 5);
		ChangeDieFace(dice2.GetDiceFaces()[num]);
		return dice2;
		void ChangeDieFace(ActionFace actionFace)
		{
			ForgeDiceReward forgeDiceReward = randomShopItems.PickRandom().Reward as ForgeDiceReward;
			actionFace.BattleAction = forgeDiceReward.DiceFace.BattleAction;
			actionFace.NewBattleAction = forgeDiceReward.DiceFace.BattleAction;
			actionFace.ActionValue = forgeDiceReward.DiceFace.ActionValue;
			actionFace.NewActionValue = forgeDiceReward.DiceFace.ActionValue;
			actionFace.EnableSecondAction = false;
			actionFace.SecondBattleAction = null;
			actionFace.SecondActionValue = 0;
			actionFace.KeepChanges = true;
		}
	}
}
